//! Textarea readOnly actions preserve actual native paint and editor/link state.
use super::*;
struct Fixture(std::path::PathBuf);
impl Drop for Fixture{fn drop(&mut self){let _=std::fs::remove_file(&self.0);}}
fn node(app:&App,id:&str)->usize{let mut pending=vec![0];while let Some(n)=pending.pop(){if app.document.dom_attr(n,"id").is_some_and(|v|v.raw_units().is_none()&&v.as_str()==id){return n;}pending.extend(app.document.nodes[n].children.iter().rev().copied());}panic!("connected node {id}")}
#[test]
fn textarea_read_only_actual_app_pointer_attribute_paint_editor_and_links(){
 let file=Fixture(std::env::temp_dir().join(format!("chezcat-app-textarea-read-only-{}.html",std::process::id())));
 std::fs::write(&file.0,r#"<!doctype html><style>body{margin:0;background:white}#paint{display:block;position:absolute;left:20px;top:20px;width:120px;height:32px;background:#114455}#paint.ready{background:#cc2244}#paint.done{background:#2244cc}#paint.removed{background:#228844}#go{position:absolute;left:220px;top:20px;width:160px;height:32px}#neighbor{position:absolute;left:220px;top:100px;width:180px;height:30px}#stable{position:absolute;left:420px;top:100px}</style><body><div id=paint>Fallback param</div><textarea id=select>Seed</textarea><input id=neighbor value=neighbor><a id=stable href=#destination>Go</a><button id=go type=button>Change metadata</button><div id=destination></div><script>var paint=document.getElementById('paint'),x=document.getElementById('select'),round=0;document.getElementById('go').onclick=function(e){if(!e.isTrusted)throw 'native pointer';var focus=document.activeElement,a=Object.getOwnPropertyDescriptor(HTMLTextAreaElement.prototype,'readOnly'),value=round!==1;x.readOnly=value;if(a.get.call(x)!==value||x.readOnly!==value||x.hasAttribute('readonly')!==value||value&&x.getAttribute('readonly')!==''||x.value!=='Seed'||x.textContent!=='Seed')throw 'actual Textarea readOnly';if(document.activeElement!==focus||document.getElementById('neighbor').value!=='edited neighbor')throw 'neighbor state';paint.className=['ready','done','removed'][round];document.title='Textarea readOnly '+round;round++;};</script>"#).unwrap();
 let mut app=App::new();app.resize(640,480);app.set_javascript_enabled(true);app.open(&file.0);assert!(!app.failed&&!app.is_loading(),"{}",app.status);assert_eq!(app.scripting.as_ref().unwrap().error_count(),0);let initial=app.draw();assert_eq!(initial.pixels[(app.content_top()+40)as usize*initial.width+110],0x114455);
 let go=node(&app,"go");let neighbor=node(&app,"neighbor");let stable=node(&app,"stable");app.forms.script_set_value(neighbor,"edited neighbor").unwrap();{let e=&mut app.forms.controls.get_mut(&neighbor).unwrap().value;e.cursor=5;e.anchor=2;e.offset=1;}let raw=app.raw.clone();let location=app.location.clone();let epoch=app.script_epoch;let scroll=app.scroll;
 for round in 0..3{let rect=app.page.controls.iter().find(|r|r.node==go).unwrap();let(x,y)=(rect.x+rect.width/2,app.content_top()+rect.y+rect.height/2-app.scroll);app.pointer_down(x,y,false);app.pointer_up(x,y);assert_eq!(app.scripting.as_ref().unwrap().error_count(),0,"{}",app.scripting.as_ref().unwrap().report());assert!(!app.failed,"{}",app.status);assert_eq!(app.document.title,format!("Textarea readOnly {round}"));let select=node(&app,"select");assert_eq!(app.forms.controls[&select].readonly,round!=1);assert_eq!(app.forms.controls[&select].value.text(),"Seed");let painted=app.draw();assert_eq!(painted.pixels[(app.content_top()+40)as usize*painted.width+110],[0xcc2244,0x2244cc,0x228844][round]);let e=&app.forms.controls[&neighbor].value;assert_eq!((e.text(),e.cursor,e.anchor,e.offset),("edited neighbor".into(),5,2,1));assert_eq!(app.page.link_node_at(430,110),Some(stable));assert_eq!(app.raw,raw);assert_eq!(app.location,location);assert_eq!(app.script_epoch,epoch);assert_eq!(app.scroll,scroll);}
}

#[test]
fn textarea_read_only_actual_app_user_typing_paste_backspace_and_reenable(){
 let file=Fixture(std::env::temp_dir().join(format!("chezcat-app-textarea-read-only-edit-{}.html",std::process::id())));
 std::fs::write(&file.0,r#"<!doctype html><style>body{margin:0}#area{position:absolute;left:20px;top:80px;width:180px;height:60px}#toggle{position:absolute;left:220px;top:20px;width:160px;height:32px}#check{position:absolute;left:420px;top:20px;width:160px;height:32px}</style><textarea id=area readonly>Seed</textarea><button id=toggle type=button>Toggle read only</button><button id=check type=button>Check</button><script>var x=document.getElementById('area'),events=0;x.oninput=function(e){if(!e.isTrusted)throw 'trusted input';events++;};document.getElementById('toggle').onclick=function(e){if(!e.isTrusted)throw 'trusted toggle';x.readOnly=!x.readOnly;};document.getElementById('check').onclick=function(e){if(!e.isTrusted||!x.readOnly||x.value!=='XY'||x.defaultValue!=='Seed'||events!==2||x.getAttributeNS(null,'readonly')!=='')throw 'actual readonly editing';document.title='Readonly user editing checked';};</script>"#).unwrap();
 let mut app=App::new();app.resize(640,480);app.set_javascript_enabled(true);app.open(&file.0);assert!(!app.failed&&!app.is_loading(),"{}",app.status);let area=node(&app,"area");let toggle=node(&app,"toggle");let check=node(&app,"check");
 fn click(app:&mut App,node:usize){let rect=app.page.controls.iter().find(|r|r.node==node).unwrap();let(x,y)=(rect.x+rect.width/2,app.content_top()+rect.y+rect.height/2-app.scroll);app.pointer_down(x,y,false);app.pointer_up(x,y);}
 click(&mut app,area);app.key(0x41,true,false,false);app.text_input('X');app.paste("Y");app.key(0x08,false,false,false);assert_eq!(app.forms.controls[&area].value.text(),"Seed");assert!(app.forms.controls[&area].readonly);
 click(&mut app,toggle);assert!(!app.forms.controls[&area].readonly);click(&mut app,area);app.key(0x41,true,false,false);app.text_input('X');app.paste("Y");assert_eq!(app.forms.controls[&area].value.text(),"XY");
 click(&mut app,toggle);assert!(app.forms.controls[&area].readonly);click(&mut app,area);app.key(0x41,true,false,false);app.text_input('Z');app.paste("Q");app.key(0x08,false,false,false);assert_eq!(app.forms.controls[&area].value.text(),"XY");click(&mut app,check);assert_eq!(app.scripting.as_ref().unwrap().error_count(),0,"{}",app.scripting.as_ref().unwrap().report());assert_eq!(app.document.title,"Readonly user editing checked");
}
